-- Mensaje 120 · Tandas 5 y 6: objeciones y consolidación (Emilio, 2-nov-2026).
-- Orden: Cerebro → reglas → habilidades → guiones → tarjetas. Todo protegido por su texto o versión de antes; el chequeo final aborta si algo no quedó.
DO $c$ DECLARE v int; BEGIN
  IF EXISTS (SELECT 1 FROM public.doctrina WHERE is_active AND strpos(body, $v$4. **Re-impulsa con una bala** `CAMPO`: una sola, y cierras. Tres de golpe sería vaciar el cargador.$v$) > 0) THEN RAISE NOTICE 'El Cerebro ya tiene los cambios del 120.'; RETURN; END IF;
  SELECT max(version) INTO v FROM public.doctrina WHERE is_active;
  IF v <> 15 THEN RAISE EXCEPTION 'se esperaba el Cerebro v15 y está el v%', v; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE version = v AND strpos(body, $v$4. **Inserta 3 balas** de la Teoría de las Balas$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro vigente no tiene el texto esperado: %', $v$4. **Inserta 3 balas** de la Teoría de las Balas$v$; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE version = v AND strpos(body, $v$**Y la bala tiene que ser NUEVA.** Repetir un argumento ya usado no sube nada: comunica que ya no tienes más, y eso baja el impulso en lugar de subirlo.$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro vigente no tiene el texto esperado: %', $v$**Y la bala tiene que ser NUEVA.** Repetir un argumento ya usado no su$v$; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE version = v AND strpos(body, $v$**R**epeat — repite la objeción en sus términos, para que vea que la escuchaste$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro vigente no tiene el texto esperado: %', $v$**R**epeat — repite la objeción en sus términos, para que vea que la e$v$; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE version = v AND strpos(body, $v$**Nunca discutas con un cliente.** Ganar la discusión es perder la venta.$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro vigente no tiene el texto esperado: %', $v$**Nunca discutas con un cliente.** Ganar la discusión es perder la ven$v$; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE version = v AND strpos(body, $v$| **FFF** — Feel, Felt, Found | Preocupación seria o personal | Nunca discutas |$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro vigente no tiene el texto esperado: %', $v$| **FFF** — Feel, Felt, Found | Preocupación seria o personal | Nunca $v$; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE version = v AND strpos(body, $v$2. **Dejarlo positivo y entendiendo los siguientes pasos** — *"la causa número uno de cancelaciones es la falta de entendimiento"*$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro vigente no tiene el texto esperado: %', $v$2. **Dejarlo positivo y entendiendo los siguientes pasos** — *"la caus$v$; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE version = v AND strpos(body, $v$**Y deja claro qué sigue.** La falta de entendimiento es la causa número uno de cancelaciones.$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro vigente no tiene el texto esperado: %', $v$**Y deja claro qué sigue.** La falta de entendimiento es la causa núme$v$; END IF;
  INSERT INTO public.doctrina (version, section_key, order_index, title, body, is_active, created_by)
  SELECT v + 1, section_key, order_index, title, replace(replace(replace(replace(replace(replace(replace(body, $v$4. **Inserta 3 balas** de la Teoría de las Balas$v$, $v$4. **Re-impulsa con una bala** `CAMPO`: una sola, y cierras. Tres de golpe sería vaciar el cargador.$v$), $v$**Y la bala tiene que ser NUEVA.** Repetir un argumento ya usado no sube nada: comunica que ya no tienes más, y eso baja el impulso en lugar de subirlo.$v$, $v$**Y la bala tiene que subir el impulso** `CAMPO`. Una bala nueva es un beneficio o un dato que todavía no habías dicho; decir lo mismo con otras palabras es repetirla. Una que ya usaste también se vale si ahora la conectas con la objeción: ante *"está caro"*, *"por eso le sale más barato: ya no pierde cambios por quedarse sin aceite"*. Lo que no sirve es repetirla tal cual, sin conectarla con nada: repetir un argumento ya usado no sube nada, comunica que ya no tienes más, y eso baja el impulso en lugar de subirlo.$v$), $v$**R**epeat — repite la objeción en sus términos, para que vea que la escuchaste$v$, $v$**R**epeat — repite la objeción en sus términos, para que vea que la escuchaste `CAMPO`: con sus palabras o muy parecido —*"o sea que el jueves no le acomoda"*—. Si la cambias por algo que no dijo, no cuenta.$v$), $v$**Nunca discutas con un cliente.** Ganar la discusión es perder la venta.$v$, $v$**Nunca discutas con un cliente.** Ganar la discusión es perder la venta. **Qué es discutir** `CAMPO`: contradecirlo o corregirlo —*"no, no está caro"*, *"usted no entiende"*—. Dar datos sin decirle que se equivoca no es discutir: *"entiendo, se ve alto; varios sintieron lo mismo, y lo que encontraron fue…"*.$v$), $v$| **FFF** — Feel, Felt, Found | Preocupación seria o personal | Nunca discutas |$v$, $v$| **FFF** — Feel, Felt, Found | Preocupación seria o personal | Nunca discutas |

**¿Cuál usar?** `CAMPO`: en el nodo que enseña una herramienta, se usa esa. En los demás, cualquiera de las dos sirve, mientras no discutas ni le saques la vuelta a la objeción.$v$), $v$2. **Dejarlo positivo y entendiendo los siguientes pasos** — *"la causa número uno de cancelaciones es la falta de entendimiento"*$v$, $v$2. **Dejarlo positivo y entendiendo los siguientes pasos** — *"la causa número uno de cancelaciones es la falta de entendimiento"*

**La otra venta escondida no es venderle más hoy** `CAMPO`: después del sí no se ofrece nada más. La otra venta son los referidos y la siguiente visita.$v$), $v$**Y deja claro qué sigue.** La falta de entendimiento es la causa número uno de cancelaciones.$v$, $v$**Y deja claro qué sigue.** La falta de entendimiento es la causa número uno de cancelaciones.

**Explicar lo que sigue no es seguir vendiendo** `CAMPO`: *"perfecto, se lo entrego el jueves en la mañana y me paga al recibir"* es lo correcto. *"¡Excelente decisión, no se va a arrepentir, con esto deja de perder clientes!"* es seguir vendiendo y festejar de más. Un *"gracias, don Chuy"* corto está bien.

**Referidos** `CAMPO`: no son obligatorios, pero se valen. Si los pides, amárralos a algo que el cliente dijo: *"me contó que su compadre tiene un taller, ¿le puedo decir que voy de su parte?"*. Pedirlos en frío —*"¿no tiene a alguien que me recomiende?"*— incomoda al cliente que acaba de comprarte.$v$), true, created_by FROM public.doctrina WHERE version = v;
  UPDATE public.doctrina SET is_active = false WHERE is_active AND version = v;
END $c$;

UPDATE public.reglas SET resumen = $v$Demostrar que nada cambió: misma indiferencia sobre la compra, misma calidez sobre la relación, cero producto. LA PRUEBA: después del sí, ¿el vendedor mantiene el mismo trato que antes, sin hablar de producto ni de beneficios?$v$, cita_cerebro = $v$Misma indiferencia sobre la compra. Misma calidez sobre la relación. Cero producto$v$, updated_at = now() WHERE id = 'consolidation.misma_actitud' AND resumen = $v$Demostrar que nada cambió: misma indiferencia sobre la compra, misma calidez sobre la relación, cero producto.$v$ AND cita_cerebro = $v$Misma indiferencia sobre la compra. Misma calidez sobre la relación. Cero producto$v$;
UPDATE public.reglas SET resumen = $v$Pedir referidos en frío incomoda al cliente que acaba de comprarte. Los referidos no son obligatorios, pero se valen si van amarrados a algo que el cliente dijo. LA PRUEBA: ¿el vendedor pide referidos sin amarrarlos a nada que el cliente haya dicho —«¿no tiene a alguien que me recomiende?», «¿me pasa unos contactos?»—, o vuelve a pedirlos después de que el cliente lo evadió?$v$, cita_cerebro = $v$Pedirlos en frío$v$, updated_at = now() WHERE id = 'consolidation.referido_en_frio' AND resumen = $v$Pedir referidos sin ancla y en tono transaccional.$v$ AND cita_cerebro = $v$la gente compra de sus amigos mucho más fácil que de un desconocido$v$;
UPDATE public.reglas SET resumen = $v$REHASH: todos tienen otra venta escondida. La otra venta no es venderle más hoy: son los referidos y la siguiente visita. LA PRUEBA: después del sí, ¿el vendedor deja abierta la siguiente oportunidad —la siguiente visita con día y propósito, o un referido amarrado a algo que el cliente dijo— sin ofrecerle nada más?$v$, cita_cerebro = $v$La otra venta escondida no es venderle más hoy$v$, updated_at = now() WHERE id = 'consolidation.rehash' AND resumen = $v$Remember Everyone Has Another Sale Hidden. Capitalizar a un cliente ya positivo.$v$ AND cita_cerebro = $v$la gente compra de sus amigos mucho más fácil que de un desconocido$v$;
UPDATE public.reglas SET resumen = $v$Salir sin dejar la puerta abierta ni cerrar en buenos términos. LA PRUEBA: al despedirse, ¿el vendedor se va brusco, cortante o resentido, sin dejar abierta la siguiente visita?$v$, cita_cerebro = $v$Dejarlo positivo y entendiendo los siguientes pasos$v$, updated_at = now() WHERE id = 'consolidation.salida_seca' AND resumen = $v$Salir sin dejar puerta abierta ni cerrar en buenos términos.$v$ AND cita_cerebro = $v$Dejarlo positivo y entendiendo los siguientes pasos$v$;
UPDATE public.reglas SET resumen = $v$Seguir vendiendo después del sí: le dice al cliente que necesitabas la venta, y toda la conversación se vuelve técnica. LA PRUEBA: después del sí, ¿el vendedor repite beneficios, el ahorro o argumentos, ofrece algo más, o le asegura que tomó una gran decisión («no se va a arrepentir»)? Explicar lo que sigue —la entrega, el pago— no es esto.$v$, cita_cerebro = $v$Retroactivamente, toda la conversación se convierte en una técnica$v$, updated_at = now() WHERE id = 'consolidation.sigue_vendiendo' AND resumen = $v$Reforzar la compra después del sí. Le dice al cliente que necesitabas la venta, y toda la conversación se vuelve técnica retroactivamente.$v$ AND cita_cerebro = $v$Retroactivamente, toda la conversación se convierte en una técnica$v$;
UPDATE public.reglas SET resumen = $v$Dejar claro qué sigue: la falta de entendimiento es la causa número uno de cancelaciones. LA PRUEBA: después del sí, ¿el vendedor deja claro qué sigue —qué se entrega, cuándo, cuánto y cómo se paga— con datos concretos (día, cantidad, monto), no vagos («ahí luego vemos»)?$v$, cita_cerebro = $v$la causa número uno de cancelaciones es la falta de entendimiento$v$, updated_at = now() WHERE id = 'consolidation.siguientes_pasos' AND resumen = $v$Dejar claro qué sigue. La falta de entendimiento es la causa número uno de cancelaciones.$v$ AND cita_cerebro = $v$la causa número uno de cancelaciones es la falta de entendimiento$v$;
UPDATE public.reglas SET resumen = $v$Festejar de más después del sí: huele a que necesitabas la venta. LA PRUEBA: ¿el vendedor celebra o elogia la decisión de forma desbordada —«¡es la mejor decisión que ha tomado!», «¡qué gusto, no sabe cuánto me alegra!»—? Un «gracias, don Chuy» corto no es esto.$v$, cita_cerebro = $v$Seguir vendiendo después del sí le dice al cliente que$v$, updated_at = now() WHERE id = 'consolidation.sobre_celebra' AND resumen = $v$Festejo desbordado tras el sí. Huele a que necesitabas la venta.$v$ AND cita_cerebro = $v$Seguir vendiendo después del sí le dice al cliente que necesitabas la venta$v$;
UPDATE public.reglas SET resumen = $v$Aplicar AIR a una objeción real: evadir a alguien que habló en serio. LA PRUEBA: ante una objeción o una preocupación real (no un «no» reflejo de la puerta), ¿el vendedor la reconoce y cambia de tema sin responderla?$v$, cita_cerebro = $v$E ignorar una objeción real ofende a alguien que sí te escuchó y sí pensó$v$, updated_at = now() WHERE id = 'objection.air_a_objecion' AND resumen = $v$Aplicar AIR a una objeción real: evadir a alguien que habló en serio.$v$ AND cita_cerebro = $v$E ignorar una objeción real ofende a alguien que sí te escuchó y sí pensó$v$;
UPDATE public.reglas SET resumen = $v$Repetir una bala tal cual: comunica que ya no tienes más, y baja el impulso en vez de subirlo. LA PRUEBA: como re-impulso, ¿el vendedor repite algo que ya había dicho —igual o con otras palabras— sin conectarlo con la objeción? Una bala ya dicha que ahora contesta la objeción («por eso le sale más barato: ya no pierde cambios») no es esto.$v$, cita_cerebro = $v$Lo que no sirve es repetirla tal cual, sin conectarla con nada$v$, updated_at = now() WHERE id = 'objection.bala_repetida' AND resumen = $v$Re-impulsar con un argumento ya usado: comunica que ya no tienes más.$v$ AND cita_cerebro = $v$Repetir un argumento ya usado no sube nada$v$;
UPDATE public.reglas SET resumen = $v$Atravesar la objeción y cerrar de inmediato, saltándose la bala: pides una decisión en el punto más bajo de la conversación. LA PRUEBA: después de atender la objeción, ¿el vendedor pide la decisión sin dar antes ninguna bala que suba el impulso?$v$, cita_cerebro = $v$El error más común: atravesar la objeción y cerrar de inmediato, saltándose la bala$v$, updated_at = now() WHERE id = 'objection.cierra_sin_bala' AND resumen = $v$Atravesar la objeción y cerrar de inmediato, saltándose la bala nueva.$v$ AND cita_cerebro = $v$El error más común: atravesar la objeción y cerrar de inmediato, saltándose la bala$v$;
UPDATE public.reglas SET resumen = $v$El Círculo de Cierre: atravesar la objeción, re-impulsar con una bala y volver a cerrar con acción. Atravesar solo detiene la caída del impulso: no lo sube. LA PRUEBA: después de atravesar la objeción, ¿el vendedor sube el impulso con una bala —nueva, o una ya dicha si ahora la conecta con la objeción— y vuelve a pedir la decisión con una pregunta de acción?$v$, cita_cerebro = $v$atravesar solo detiene la caída del impulso$v$, updated_at = now() WHERE id = 'objection.circulo_de_cierre' AND resumen = $v$Atravesar la objeción, re-impulsar con una bala NUEVA, y cerrar.$v$ AND cita_cerebro = $v$atravesar solo detiene la caída del impulso — no lo sube$v$;
UPDATE public.reglas SET resumen = $v$Discutir con el cliente: ganar la discusión es perder la venta. LA PRUEBA: ante una objeción, ¿el vendedor contradice o corrige al cliente —«no, no está caro», «usted no entiende», «eso no fue culpa nuestra»— o se justifica a la defensiva? Dar datos sin decirle que se equivoca no es discutir.$v$, cita_cerebro = $v$Ganar la discusión es perder la venta$v$, updated_at = now() WHERE id = 'objection.discutir' AND resumen = $v$Discutir con el cliente. Ganar la discusión es perder la venta.$v$ AND cita_cerebro = $v$Nunca discutas con un cliente. Ganar la discusión es perder la venta$v$;
UPDATE public.reglas SET resumen = $v$Feel, Felt, Found para la preocupación seria o personal: «entiendo cómo se siente», «otros sintieron lo mismo», «lo que encontraron fue…». No termina en la tercera F: sigue una bala y el cierre con acción. LA PRUEBA: ante una objeción seria, ¿el vendedor la valida sin discutir, dice que otros sintieron lo mismo y lo que encontraron, y avanza? En la práctica los otros clientes se imaginan. Si falta una de las tres F, está a medias.$v$, cita_cerebro = $v$FFF no termina en la tercera F$v$, updated_at = now() WHERE id = 'objection.fff' AND resumen = $v$Feel, Felt, Found, más tres balas y Close With Action. No termina en la tercera F.$v$ AND cita_cerebro = $v$FFF no termina en la tercera F$v$;
UPDATE public.reglas SET resumen = $v$RRR para objeciones menores y comunes (precio, día de entrega, mínimo): Repeat, Reassure, Resume. LA PRUEBA: ¿el vendedor (1) repite la objeción con las palabras del cliente o muy parecido —«o sea que el jueves no le acomoda»—, (2) responde con algo concreto y (3) retoma sin pausa? Si falta una pieza, está a medias. Si cambia la objeción por algo que el cliente no dijo, no cuenta como repetirla.$v$, cita_cerebro = $v$repite la objeción en sus términos, para que vea que la escuchaste$v$, updated_at = now() WHERE id = 'objection.rrr' AND resumen = $v$Repeat, Reassure, Resume. Para objeciones menores y comunes.$v$ AND cita_cerebro = $v$repite la objeción en sus términos, para que vea que la escuchaste$v$;
UPDATE public.reglas SET resumen = $v$Responder bien y quedarse callado: en ese silencio el cliente encuentra la siguiente objeción o dice que lo va a pensar. LA PRUEBA: después de responder la objeción, ¿el vendedor termina su turno sin retomar —sin una pregunta, el siguiente paso o seguir donde iba—, esperando a ver si convenció?$v$, cita_cerebro = $v$La tercera R es la que falla$v$, updated_at = now() WHERE id = 'objection.rrr_sin_resume' AND resumen = $v$Responder bien y quedarse callado. Ahí el cliente encuentra la siguiente objeción.$v$ AND cita_cerebro = $v$La tercera R es la que falla$v$;
UPDATE public.reglas SET resumen = $v$Que la segunda objeción le drene el ánimo: la actitud es la variable de entrada. LA PRUEBA: ante otra objeción, ¿el vendedor se encoge en lo que dice —contesta cada vez más corto, en tono de resignación o fastidio, o empieza a rendirse—?$v$, cita_cerebro = $v$interactuar de más con él desgasta tu actitud, que es la variable de entrada de todo tu sistema$v$, updated_at = now() WHERE id = 'objection.se_desanima' AND resumen = $v$La segunda objeción drena el ánimo. KILT: la actitud es la variable de entrada.$v$ AND cita_cerebro = $v$interactuar de más con él desgasta tu actitud, que es la variable de entrada de todo tu sistema$v$;
UPDATE public.reglas SET resumen = $v$Apilar argumentos en una respuesta: las balas se dosifican. LA PRUEBA: al atender una objeción, ¿el vendedor suelta dos o más balas en la misma respuesta, en vez de una sola antes de cerrar?$v$, cita_cerebro = $v$Reserva algunas para que no importe cuántas balas tenga tu cliente$v$, updated_at = now() WHERE id = 'objection.vacia_el_cargador' AND resumen = $v$Apilar argumentos en una respuesta. Las balas se dosifican.$v$ AND cita_cerebro = $v$Reserva algunas para que no importe cuántas balas tenga tu cliente$v$;


